``` 1 from __future__ import annotations 2 3 import json 4 from pathlib import Path 5 6 import pytest 7 8 from chats import ConversationFlags, cmd_parse 9 10 FIXTURES_DIR = Path(__file__).parent / "data" / "json_format" 11 12 13 def _install_fixture(temp_home: Path, provider: str, fixture_name: str) -> Path: 14 fixture_content = (FIXTURES_DIR / fixture_name).read_text(encoding="utf-8") 15 16 if provider == "claude": 17 target_path = ( 18 temp_home 19 / ".claude" 20 / "projects" 21 / "demo-project" 22 / fixture_name 23 ) 24 elif provider == "pi": 25 target_path = ( 26 temp_home 27 / ".pi" 28 / "agent" 29 / "sessions" 30 / "demo-project" 31 / fixture_name 32 ) 33 elif provider == "codex": 34 target_path = ( 35 temp_home 36 / ".codex" 37 / "sessions" 38 / "2026" 39 / "05" 40 / "12" 41 / fixture_name.replace("input-", "rollout-2026-05-12T10-00-00-") 42 ) 43 else: 44 raise ValueError(f"Unsupported provider: {provider}") 45 46 target_path.parent.mkdir(parents=True, exist_ok=True) 47 target_path.write_text(fixture_content, encoding="utf-8") 48 return target_path 49 50 51 @pytest.fixture 52 def temp_home(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path: 53 monkeypatch.setenv("HOME", str(tmp_path)) 54 return tmp_path 55 56 57 @pytest.mark.parametrize( 58 ("provider", "fixture_name", "flags", "expected_name"), 59 [ 60 ( 61 "claude", 62 "input-claude-no-tools.jsonl", 63 ConversationFlags(color="never"), 64 "expected-claude-no-tools.json", 65 ), 66 ( 67 "claude", 68 "input-claude-with-thinking.jsonl", 69 ConversationFlags(show_thinking=True, color="never"), 70 "expected-claude-with-thinking.json", 71 ), 72 ( 73 "claude", 74 "input-claude-with-tools.jsonl", 75 ConversationFlags(show_tools=True, color="never"), 76 "expected-claude-with-tools.json", 77 ), 78 ( 79 "pi", 80 "input-pi-no-tools.jsonl", 81 ConversationFlags(color="never"), 82 "expected-pi-no-tools.json", 83 ), 84 ( 85 "pi", 86 "input-pi-with-thinking.jsonl", 87 ConversationFlags(show_thinking=True, color="never"), 88 "expected-pi-with-thinking.json", 89 ), 90 ( 91 "pi", 92 "input-pi-with-tools.jsonl", 93 ConversationFlags(show_tools=True, color="never"), 94 "expected-pi-with-tools.json", 95 ), 96 ( 97 "codex", 98 "input-codex-no-tools.jsonl", 99 ConversationFlags(color="never"), 100 "expected-codex-no-tools.json", 101 ), 102 ( 103 "codex", 104 "input-codex-with-thinking.jsonl", 105 ConversationFlags(show_thinking=True, color="never"), 106 "expected-codex-with-thinking.json", 107 ), 108 ( 109 "codex", 110 "input-codex-with-tools.jsonl", 111 ConversationFlags(show_tools=True, color="never"), 112 "expected-codex-with-tools.json", 113 ), 114 ], 115 ) 116 def test_json_output_is_fully_structured( 117 temp_home: Path, 118 capsys: pytest.CaptureFixture[str], 119 provider: str, 120 fixture_name: str, 121 flags: ConversationFlags, 122 expected_name: str, 123 ) -> None: 124 fixture_path = _install_fixture(temp_home, provider, fixture_name) 125 expected = json.loads((FIXTURES_DIR / expected_name).read_text(encoding="utf-8")) 126 127 cmd_parse( 128 flags, 129 str(fixture_path), 130 None, 131 None, 132 output_format="json", 133 emit_metadata=False, 134 ) 135 136 captured = capsys.readouterr() 137 actual = json.loads(captured.out) 138 139 assert actual == expected, ( 140 f"Expected structured JSON output for {provider}/{fixture_name}.
